&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Work in office and technical environments with occasional exposure to&amp;nbsp;noise,&amp;nbsp;dust&amp;nbsp;and fumes&amp;nbsp;in production areas.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
